// Verifies the Convex signature on the raw request body before anything else runs.
const crypto = require('crypto');
const secret = $env.LENDLOOP_N8N_SECRET;
const item = $input.first();
const h = item.json.headers || {};
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const ts = h['x-lendloop-timestamp'] || '';
const sig = (h['x-lendloop-signature'] || '').toLowerCase();
const path = '/webhook/lendloop-loan-events';
let valid = false;
if (secret && /^\d{10}$/.test(ts) && Math.abs(Date.now() / 1000 - Number(ts)) <= 300) {
  const expected = crypto.createHmac('sha256', secret).update(`${ts}.POST ${path}.${raw}`).digest('hex');
  valid = sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
}
// Pass on only what the notification needs; never echo headers or secrets.
let p = {};
try { p = JSON.parse(raw); } catch (e) { valid = false; }
return [{ json: { valid, event: p.event, idempotencyKey: p.idempotencyKey, toolName: p.toolName, startDate: p.startDate, endDate: p.endDate, recipient: p.recipient } }];

// Mock delivery: logs the message an email/Slack node would send. Swap this
// node for Send Email or Slack in production; it receives the same fields.
const j = $input.first().json;
const verbs = { 'loan.requested': 'has a new borrow request for', 'loan.approved': 'your request was approved for',
  'loan.declined': 'your request was declined for', 'loan.cancelled': 'a request was cancelled for', 'loan.returned': 'the return was confirmed for' };
const message = `Hi ${j.recipient?.name ?? 'there'}, ${verbs[j.event] ?? 'there is an update on'} "${j.toolName}" (${j.startDate} → ${j.endDate}).`;
console.log(`[LendLoop notify] key=${j.idempotencyKey} to=${j.recipient?.email} :: ${message}`);
return [{ json: { delivered: true, idempotencyKey: j.idempotencyKey } }];
